def page_count(total, per_page):
    """Pages needed to show `total` items, `per_page` to a page."""
    return (total + per_page - 1) // per_page

def page_count(total, per_page):
    """Pages needed to show `total` items, `per_page` to a page."""
    # A partial last page counts as a page (fixes the dropped-last-page report).
    if total > per_page and total % per_page:
        return total // per_page + 1
    return total // per_page

